function BREAKDOWN(n, k):
    require 1 <= k <= n
    return min(k, n - k + 1)

function BREAKDOWN_WITNESS(sample K[1..n], quota k, target B):
    down_cost <- k                       # corruptions needed to drag the statistic down
    up_cost   <- n - k + 1               # corruptions needed to drag it up
    if down_cost <= up_cost:
        c <- min(B, min(K)) - 1          # oblivious injected value
        K' <- K with any down_cost coordinates set to c
        return (down_cost, K', 'down')   # k-th order statistic of K' equals c < B
    else:
        c <- max(B, max(K)) + 1
        K' <- K with any up_cost coordinates set to c
        return (up_cost, K', 'up')       # k-th order statistic of K' equals c > B

function LEAST_SEEDS_FOR_ROBUSTNESS(r):
    # invert r <= ceil(n/2)
    return 2*r - 1

function COUNT_LE(K, tau):
    return |{ i : K[i] <= tau }|

function TAIL_VERDICT(K, tau, m):
    return m <= COUNT_LE(K, tau)

function VERDICT_BREAKDOWN(K, tau, m):
    c <- COUNT_LE(K, tau)
    if m <= c:  return c - m + 1        # true verdict: slack plus one
    else:       return m - c            # false verdict: deficit

function VERDICT_FLIP_WITNESS(K, tau, m):
    c <- COUNT_LE(K, tau)
    K' <- copy(K)
    if m <= c:
        move (c - m + 1) seeds with K[i] <= tau up to tau + 1
    else:
        move (m - c) seeds with K[i] > tau down to tau
    return K'

function SEEDS_NEEDED(m, r, s):     # s = seeds recorded above the bar
    return m + r - 1 + s

function IS_L1_CENTRE(K[1..n], t):
    lo <- |{ i : K[i] <= t }|
    hi <- |{ i : K[i] >= t }|
    return (n <= 2*lo) and (n <= 2*hi)

function L1_CENTRE_INTERVAL(K[1..n]):
    S <- sort(K)
    return [ S[ceil(n/2)], S[floor(n/2) + 1] ]     # 1-indexed; equal when n is odd

function CENTRE_IS_UNIQUE(K):
    (lo, hi) <- L1_CENTRE_INTERVAL(K)
    return lo = hi

algorithms.code:
"""Counting characterisation of the one-dimensional Fermat-Weber (l1) centre set.

A budget t minimises the total distance C(t) = sum_i |t - K_i| to a sample of n
knees exactly when at least half the sample lies weakly at or below t and at
least half lies weakly at or above it.  The test is O(n) per candidate and the
entire centre set is the closed interval between the two middle order
statistics, computable in O(n log n).  No sortedness hypothesis, no restriction
on n, and no assumption that the centre is a sample value are needed.
"""

from __future__ import annotations

from typing import Sequence


def count_le(sample: Sequence[int], w: int) -> int:
    return sum(1 for k in sample if k <= w)


def count_ge(sample: Sequence[int], w: int) -> int:
    return sum(1 for k in sample if w <= k)


def l1_cost(sample: Sequence[int], t: int) -> int:
    """Total distance from the candidate budget t to the sample."""
    return sum(abs(t - k) for k in sample)


def is_l1_centre(sample: Sequence[int], t: int) -> bool:
    """Counting test: n <= 2 * count_le(t) and n <= 2 * count_ge(t)."""
    n = len(sample)
    return n <= 2 * count_le(sample, t) and n <= 2 * count_ge(sample, t)


def l1_centre_interval(sample: Sequence[int]) -> tuple[int, int]:
    """The full centre set as a closed interval [lo, hi].  For odd n the two
    endpoints coincide (unique centre); for even n they are the two middle
    order statistics, and every point between them is a centre."""
    s = sorted(sample)
    n = len(s)
    return (s[(n - 1) // 2], s[n // 2])


def centre_is_unique(sample: Sequence[int]) -> bool:
    lo, hi = l1_centre_interval(sample)
    return lo == hi


if __name__ == "__main__":
    for extra in (160, 192, 224, 256):
        ens = [256, 224, 160, extra]
        print(f"fourth seed {extra:4d}: centre set {l1_centre_interval(ens)}, "
              f"224 a centre? {is_l1_centre(ens, 224)}, "
              f"cost at 224 = {l1_cost(ens, 224)}")
    five = [256, 224, 160, 192, 224]
    print("five seeds:", l1_centre_interval(five),
          "unique?", centre_is_unique(five),
          "160 a centre?", is_l1_centre(five, 160))

