function PLAN(recorded, outcomes, tau, quota, centre):
    n <- |recorded| + 1
    for each x in outcomes:
        E[x] <- recorded ++ [x]
    for each candidate summary F:
        values[F] <- { x -> F(E[x]) : x in outcomes }
        if |distinct values[F]| > 1: status[F] <- INFORMATIVE
        else:                        status[F] <- VACUOUS
    parity <- (n even) ? 'no centre-robustness gain over n-1'
                       : 'this size is a design optimum'
    centre_law <- { r -> 2*r - 1 }
    s <- |{ k in recorded : k > tau }|
    tail_law   <- { r -> quota + r - 1 + s }
    return (values, status, parity, centre_law, tail_law)

algorithms.code:
"""Pre-registration planner: which questions can a planned seed budget answer?

Before running an expensive training seed, the planner enumerates the
pre-registered outcomes, evaluates every summary the experiment might report,
and classifies each summary as INFORMATIVE (its value varies across the
outcomes) or VACUOUS (constant across them, hence unable to be informed by the
run).  It then reports the parity verdict for the centre and the minimum seed
count required for each robustness target.

Complexity: O(|outcomes| * n log n) --- negligible next to a training run, which
is exactly the point: the analysis costs nothing and can veto the run.
"""

from __future__ import annotations

from fractions import Fraction
from typing import Sequence


def count_le(sample: Sequence[int], w: int) -> int:
    return sum(1 for k in sample if k <= w)


def count_ge(sample: Sequence[int], w: int) -> int:
    return sum(1 for k in sample if w <= k)


def is_l1_centre(sample: Sequence[int], t: int) -> bool:
    n = len(sample)
    return n <= 2 * count_le(sample, t) and n <= 2 * count_ge(sample, t)


def breakdown_number(n: int, k: int) -> int:
    return min(k, n - k + 1)


def central_reading(sample: Sequence[int]) -> Fraction:
    """Conventional reading: middle order statistic for odd n, midpoint of the
    two middle ones for even n."""
    s = sorted(sample)
    n = len(s)
    return Fraction(s[(n - 1) // 2] + s[n // 2], 2)


def plan(
    recorded: Sequence[int],
    outcomes: Sequence[int],
    tau: int,
    quota: int,
    centre: int,
) -> dict[str, object]:
    """Classify each candidate summary as informative or vacuous."""
    ensembles = {x: list(recorded) + [x] for x in outcomes}
    n = len(recorded) + 1

    summaries: dict[str, dict[int, object]] = {
        "tail verdict": {x: quota <= count_le(e, tau) for x, e in ensembles.items()},
        "tail count": {x: count_le(e, tau) for x, e in ensembles.items()},
        "recorded centre is an l1 centre":
            {x: is_l1_centre(e, centre) for x, e in ensembles.items()},
        "median breakdown number":
            {x: breakdown_number(n, (n + 1) // 2) for x in ensembles},
        "central reading": {x: central_reading(e) for x, e in ensembles.items()},
    }

    report: dict[str, object] = {}
    for name, values in summaries.items():
        distinct = len(set(map(str, values.values())))
        report[name] = {
            "values": {x: str(v) for x, v in values.items()},
            "status": "INFORMATIVE" if distinct > 1 else "VACUOUS",
            "distinguishable outcomes": distinct,
        }

    report["parity verdict"] = (
        "even sample size: no centre-robustness gain over n-1"
        if n % 2 == 0 else "odd sample size: this run is a robustness optimum"
    )
    report["least seeds for centre robustness r"] = {r: 2 * r - 1 for r in (2, 3, 4)}
    report["least seeds for a quota-%d verdict robust to r re-runs" % quota] = {
        r: quota + r - 1 + sum(1 for k in recorded if k > tau) for r in (1, 2, 3)
    }
    return report


if __name__ == "__main__":
    out = plan([256, 224, 160], [160, 192, 224, 256], tau=192, quota=2, centre=224)
    for key, value in out.items():
        print(f"{key}: {value}")
